+#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
+#[repr(u8)]
+pub enum EdgeKind {
+    Refinement = 0,
+    Overlap = 1,
+    Forward = 2,
+}
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct Edge {
+    pub id: u32,
+    pub src: u32,
+    pub dst: u32,
+    pub weight: u32,
+    pub score: ScoreQ,
+    pub kind: EdgeKind,
+}
